// ELEMENTS:
// 1. Foto/vídeo opcional (src) em ecrã inteiro, escurecido por navy a 78% — só ambiente
// 2. Barra azul IAD curta
// 3. Frase grande em serifa branca (anim.text), palavra a palavra em fade suave
// 4. Assinatura opcional (sub) em branco, tracking largo
// 5. Grão de filme + vinheta
import React, { useId } from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, Easing } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#001F44";
const CYAN = "#DE212B";
const CORAL = "#DE212B";
const WHITE = "#FFFFFF";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const Grain: React.FC<{ f: number }> = ({ f }) => {
  const id = useId().replace(/:/g, "");
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.26) 100%)" }} />
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0, opacity: 0.1, mixBlendMode: "overlay" }}>
        <filter id={id}>
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={f % 12} />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${id})`} />
      </svg>
    </AbsoluteFill>
  );
};

const CitacaoEditorial: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const H = box.height;
  const land = format === "landscape";
  const u = land ? H / 1080 : format === "half" ? (H / 960) * 0.85 : W / 1080;
  const T = Math.max(2, Math.round((anim.end - anim.start) * fps));
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const src = String(p.src ?? "");
  const sub = String(p.sub ?? "").trim();
  const words = String(anim.text ?? "").trim().split(/\s+/).filter(Boolean);

  const t = (delay: number, len = 0.7): number =>
    interpolate(f, [Math.round(delay * fps), Math.round((delay + len) * fps)], [0, 1], { ...clamp, easing: EASE });
  const drift = interpolate(f, [0, T], [1.06, 1.14], clamp);
  const size = Math.min(120 * u, ((land ? W * 0.7 : W) - 192 * u) / Math.max(5, Math.sqrt(words.join(" ").length) * 1.6));
  const step = Math.min(0.14, 1.2 / Math.max(1, words.length));

  return (
    <AbsoluteFill style={{ textShadow: "0 2px 18px rgba(0,0,0,0.45)", overflow: "hidden", backgroundColor: NAVY }}>
      {src ? (
        <AbsoluteFill style={{ transform: `scale(${drift})`, opacity: 0.9 }}>
          <Img src={src} style={{ width: "100%", height: "100%", objectFit: "cover", filter: "saturate(0.7)" }} />
        </AbsoluteFill>
      ) : null}
      <AbsoluteFill style={{ backgroundColor: "rgba(22,22,23,0.78)" }} />
      <div
        style={{
          position: "absolute",
          left: 96 * u,
          right: 96 * u,
          top: "50%",
          transform: "translateY(-50%)",
          display: "flex",
          flexDirection: "column",
          alignItems: "flex-start",
          gap: 48 * u,
        }}
      >
        <div style={{ width: interpolate(t(0.1, 0.8), [0, 1], [0, 96 * u]), height: 4 * u, background: CYAN }} />
        <div style={{ fontFamily: FONTS.display, fontVariantNumeric: "lining-nums", fontWeight: 300, fontSize: size, lineHeight: 1.08, color: WHITE }}>
          {words.map((w, i) => {
            const k = t(0.3 + i * step, 0.6);
            return (
              <span key={i} style={{ display: "inline-block", opacity: k, transform: `translateY(${(1 - k) * 16 * u}px)`, marginRight: "0.25em" }}>
                {w}
              </span>
            );
          })}
        </div>
        {sub ? (
          <div
            style={{
              fontFamily: FONTS.body,
              fontWeight: 600,
              fontSize: 36 * u,
              letterSpacing: "0.22em",
              textTransform: "uppercase",
              color: WHITE,
              opacity: t(0.5 + words.length * step),
            }}
          >
            {sub}
          </div>
        ) : null}
      </div>
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 6 * u, background: "#DE212B" }} />
      <Grain f={f} />
    </AbsoluteFill>
  );
};

export default CitacaoEditorial;
